// 组件源码（index.ts）与设计画布里渲染组件稿的那一份完全相同，这里把它的 h() 接到 React 上。
import { createElement, Fragment } from "react"
import type { CSSProperties, ReactNode } from "react"

export type KitStyle = CSSProperties
export type KitNode = ReactNode
export type KitChildren = ReactNode
export type KitComponent<P> = (props: P) => ReactNode

